// Huni grafiğinin saf mantığı: görünüme göre bant dizilimi, oranlar ve yazımlar. Sayılar ABACUS'tandır (chart-format).
import { formatChange, formatCompact, formatMoney, formatMoneyCompact, formatNumber, formatRatio } from "../lib/chart-format";

export interface FunnelPart { key: string; label: string; value: number }
export interface FunnelStep { key: string; label: string; value: number; /** Adımın parça kırılımı (isteğe bağlı). Toplamı `value` olmalıdır. */ parts?: FunnelPart[] | undefined }
export type FunnelKind = "count" | "money";
/** "total": tek bant, "split": parçalar üst üste, başka bir değer: yalnız o parça (parça anahtarı). */
export type FunnelView = "total" | "split" | string;

export interface FunnelBand { key: string; label: string; /** Her adımda bandın üst ve alt kenarı, 0–1 arası (genişlik ekseni oranı). */ top: number[]; bottom: number[] }

/** Adımlardaki parça anahtarları, ilk görülme sırasıyla. */
export function partKeys(steps: FunnelStep[]): FunnelPart[] {
  const seen = new Map<string, FunnelPart>();
  for (const step of steps) for (const part of step.parts ?? []) if (!seen.has(part.key)) seen.set(part.key, part);
  return [...seen.values()];
}

/**
 * Görünüme göre bantları dizer. Toplam: tek bant, yüksekliği adım değeri / en büyük değer.
 * Bölünmüş: parçalar aralarında `gap` boşlukla üst üste. Tek parça: bant en büyük değerine göre ölçeklenir ve yüksekliği doldurur.
 */
export function funnelBands(steps: FunnelStep[], view: FunnelView, gap = .015): FunnelBand[] {
  if (!steps.length) return [];
  const parts = partKeys(steps);
  const valueOf = (step: FunnelStep, key: string) => step.parts?.find(part => part.key === key)?.value ?? 0;
  if (view === "total" || (view !== "split" && !parts.some(part => part.key === view))) {
    const max = Math.max(...steps.map(step => step.value), 0) || 1;
    const half = steps.map(step => step.value / max / 2);
    return [{ key: "total", label: "Toplam", top: half.map(h => .5 - h), bottom: half.map(h => .5 + h) }];
  }
  if (view === "split") {
    const max = Math.max(...steps.map(step => step.value), 0) || 1;
    return parts.map((part, at) => {
      const top: number[] = [], bottom: number[] = [];
      for (const step of steps) {
        const height = step.value / max, room = Math.max(0, height - gap * (parts.length - 1));
        const share = step.value > 0 ? valueOf(step, part.key) / step.value : 0;
        const before = parts.slice(0, at).reduce((sum, other) => sum + (step.value > 0 ? valueOf(step, other.key) / step.value : 0), 0);
        const start = (1 - height) / 2 + before * room + gap * at;
        top.push(start); bottom.push(start + share * room);
      }
      return { key: part.key, label: part.label, top, bottom };
    });
  }
  const own = steps.map(step => valueOf(step, view));
  const max = Math.max(...own, 0) || 1;
  const part = parts.find(item => item.key === view)!;
  return [{ key: part.key, label: part.label, top: own.map(v => .5 - v / max / 2), bottom: own.map(v => .5 + v / max / 2) }];
}

/** Bir adımın bir önceki adımdan ve ilk adımdan oranları (0–1); ilk adımın önceki oranı yoktur. */
export function stepRatios(steps: FunnelStep[], at: number): { previous: number | null; first: number } {
  const step = steps[at], first = steps[0];
  if (!step || !first) return { previous: null, first: 0 };
  const before = steps[at - 1];
  return { previous: before && before.value > 0 ? step.value / before.value : null, first: first.value > 0 ? step.value / first.value : 0 };
}

export const countText = (kind: FunnelKind, value: number) => kind === "money" ? formatMoney(value, 0) : formatNumber(value, 0);
export const shortText = (kind: FunnelKind, value: number) => kind === "money" ? formatMoneyCompact(value) : formatCompact(value);
export const ratioText = (ratio: number) => formatRatio(ratio, 1);
/** Düşüş yazımı: "↓ 340 (-%12,3)". */
export function dropText(kind: FunnelKind, from: number, to: number): string {
  return `↓ ${countText(kind, Math.max(0, from - to))} (${formatChange(to, from, 1)})`;
}

/** Ekran okuyucu: "Ödeme: 540, önceki adımdan %45 kaldı, ilk adıma göre %12". */
export function stepAnnouncement(kind: FunnelKind, steps: FunnelStep[], at: number): string {
  const step = steps[at];
  if (!step) return "";
  const { previous, first } = stepRatios(steps, at);
  return `${step.label}: ${countText(kind, step.value)}${previous === null ? "" : `, önceki adımdan ${ratioText(previous)} kaldı`}, ilk adıma göre ${ratioText(first)}`;
}

.figure { display: grid; min-width: 0; gap: var(--space-4); margin: 0; color: var(--foreground); }
.head { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.titles { min-width: 0; }
.title { font-family: var(--font-display); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-display); }
.description { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.body { position: relative; display: grid; min-width: 0; gap: var(--space-2); }
.heads { display: grid; }
.stepHead { display: grid; gap: 2px; padding: 0 var(--space-2); text-align: center; transition: background var(--duration-fast) var(--ease-standard); border-radius: var(--radius-control); }
.stepHead[data-active] { background: var(--accent-subtle); }
.stepName { color: var(--text-secondary); font-size: var(--text-sm); overflow-wrap: anywhere; }
.stepValue { font-family: var(--font-display); font-size: var(--text-xl); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.stepRatio { color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.stage { position: relative; min-width: 0; }
.body[data-vertical] .stage { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-3); }
.rows { display: grid; grid-auto-rows: 1fr; }
.rows .stepHead { align-content: center; text-align: left; }
.focus { position: relative; outline: none; border-radius: var(--radius-control); }
.focus:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: var(--focus-outline-offset, 2px); }
.svg { display: block; max-width: 100%; touch-action: pan-y; }
.column { fill: var(--accent-subtle); transition: x var(--duration-standard) var(--ease-standard), y var(--duration-standard) var(--ease-standard); }
.bands { transform-origin: center; transform: scaleY(.02); opacity: 0; transition: transform var(--duration-considered) var(--ease-enter), opacity var(--duration-standard) var(--ease-standard); }
.bands[data-vertical] { transform: scaleX(.02); }
.svg[data-revealed] .bands { transform: none; opacity: 1; }
.band { opacity: .82; transition: d var(--duration-considered) var(--ease-standard), fill var(--duration-standard) var(--ease-standard); }
.dot { fill: var(--surface); opacity: .8; pointer-events: none; }
.drops { position: relative; height: 1.25rem; margin-top: var(--space-1); }
.drop { position: absolute; transform: translateX(-50%); color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; white-space: nowrap; }
.tip { position: absolute; z-index: 1; top: 0; display: grid; gap: 2px; min-width: 9rem; padding: var(--space-2) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-raised); box-shadow: var(--shadow-raised); font-size: var(--text-xs); pointer-events: none; transform: translateX(-50%); }
.body[data-vertical] .tip { transform: none; }
.tipPart { color: var(--text-secondary); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.skeleton { height: 14rem; border-radius: var(--radius-control); background: var(--surface-muted); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.figure[data-reduced] .bands, .figure[data-reduced] .band, .figure[data-reduced] .column, .figure[data-reduced] .stepHead { transition: none; transform: none; opacity: 1; }
@media (prefers-reduced-motion: reduce) { .bands, .band, .column, .stepHead { transition: none; } }

"use client";

import { useEffect, useId, useMemo, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { clamp, seriesColor, useElementWidth, useOnScreen, useReducedMotionSafe } from "../lib/viz-utils";
import SegmentedControl from "../segmented-control/segmented-control";
import { countText, dropText, funnelBands, partKeys, ratioText, shortText, stepAnnouncement, stepRatios, type FunnelBand, type FunnelKind, type FunnelPart, type FunnelStep, type FunnelView } from "./funnel-chart-format";
import styles from "./funnel-chart.module.css";

export type { FunnelKind, FunnelPart, FunnelStep, FunnelView };

/** Adım adım daralan bir süreci (ziyaretçi → sipariş, teklif → sözleşme) göstermek için kullanın; dallanan akış için akış şeması daha doğrudur. */
export interface FunnelChartProps {
  steps: FunnelStep[];
  /** Neyin daraldığı, örneğin "Satış hunisi". */
  label: string;
  description?: string | undefined;
  /** "count": adet; "money": TRY tutar. */
  kind?: FunnelKind | undefined;
  /** Parçalı veride görünüm seçicisini gösterir (Toplam / Bölünmüş / her parça). */
  showViews?: boolean | undefined;
  /** Sağ üstte duran ek denetimler. */
  actions?: ReactNode | undefined;
  loading?: boolean | undefined;
  emptyText?: string | undefined;
}

const HEIGHT = 220, ROW = 76, NARROW = 420, PLATEAU = .14;

type Point = { along: number; across: number };
/** Noktalardan geçen yumuşak yol: her iki nokta arasında yatay teğetli bir eğri (düz parçalar doğru olur). */
function curveThrough(points: Point[], map: (along: number, across: number) => { x: number; y: number }) {
  const first = map(points[0]!.along, points[0]!.across);
  let d = `M${first.x} ${first.y}`;
  for (let at = 1; at < points.length; at++) {
    const p = points[at - 1]!, q = points[at]!, mid = (p.along + q.along) / 2;
    const c0 = map(mid, p.across), c1 = map(mid, q.across), end = map(q.along, q.across);
    d += `C${c0.x} ${c0.y} ${c1.x} ${c1.y} ${end.x} ${end.y}`;
  }
  return d;
}

export function FunnelChart({ steps, label, description, kind = "count", showViews = true, actions, loading = false, emptyText = "Veri yok." }: FunnelChartProps) {
  const reduced = useReducedMotionSafe();
  const titleId = useId();
  const [box, width] = useElementWidth<HTMLDivElement>();
  const [visibleRef, onScreen] = useOnScreen<HTMLElement>();
  const [view, setView] = useState<FunnelView>("total");
  const [active, setActive] = useState<number | null>(null);
  const [revealed, setRevealed] = useState(false);
  useEffect(() => { const frame = requestAnimationFrame(() => setRevealed(true)); return () => cancelAnimationFrame(frame); }, []);

  const parts = useMemo(() => partKeys(steps), [steps]);
  const bands = useMemo(() => funnelBands(steps, view), [steps, view]);
  const vertical = width > 0 && width < NARROW;
  const count = steps.length;
  const length = vertical ? count * ROW : Math.max(width, 1);
  const breadth = vertical ? Math.max(width * .6, 120) : HEIGHT;
  const stepSize = length / Math.max(count, 1);
  const map = (along: number, across: number) => vertical ? { x: across * breadth, y: along } : { x: along, y: across * breadth };

  const bandPath = (band: FunnelBand) => {
    const forward = (values: number[]) => values.flatMap((value, at) => [{ along: at * stepSize + (at === 0 ? 0 : stepSize * PLATEAU), across: value }, { along: (at + 1) * stepSize - (at === count - 1 ? 0 : stepSize * PLATEAU), across: value }]);
    const top = forward(band.top), bottom = forward(band.bottom).reverse();
    const tail = curveThrough(bottom, map).replace(/^M[^C]*/, "");
    const join = map(bottom[0]!.along, bottom[0]!.across);
    return `${curveThrough(top, map)}L${join.x} ${join.y}${tail}Z`;
  };
  const centerPath = (band: FunnelBand) => curveThrough(band.top.flatMap((value, at) => {
    const across = (value + band.bottom[at]!) / 2;
    return [{ along: at * stepSize + (at === 0 ? 0 : stepSize * PLATEAU), across }, { along: (at + 1) * stepSize - (at === count - 1 ? 0 : stepSize * PLATEAU), across }];
  }), map);

  const pick = (at: number | null) => setActive(at === null ? null : clamp(at, 0, count - 1));
  const stepAt = (event: PointerEvent<SVGSVGElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const along = vertical ? event.clientY - rect.top : event.clientX - rect.left;
    return clamp(Math.floor(along / stepSize), 0, count - 1);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const keys: Record<string, number | null> = { ArrowRight: (active ?? -1) + 1, ArrowDown: (active ?? -1) + 1, ArrowLeft: (active ?? count) - 1, ArrowUp: (active ?? count) - 1, Home: 0, End: count - 1, Escape: null };
    if (!(event.key in keys)) return;
    event.preventDefault();
    pick(keys[event.key]!);
  };

  const viewOptions = [{ value: "total", label: "Toplam" }, { value: "split", label: "Bölünmüş" }, ...parts.map(part => ({ value: part.key, label: part.label }))];
  const footprint = active === null ? null : steps[active];
  const ratios = active === null ? null : stepRatios(steps, active);
  const tipCenter = active === null ? 0 : vertical ? 0 : clamp((active + .5) * stepSize, 110, Math.max(110, length - 110));

  if (loading) return <figure className={styles.figure} aria-busy="true" aria-label={`${label} yükleniyor`}><div className={styles.skeleton} /></figure>;
  const empty = !steps.length || !(steps[0]?.value && steps[0].value > 0);

  const heads = steps.map((step, at) => {
    const { previous } = stepRatios(steps, at);
    return <div key={step.key} className={styles.stepHead} data-active={active === at || undefined}>
      <span className={styles.stepName}>{step.label}</span>
      <span className={styles.stepValue}>{shortText(kind, step.value)}</span>
      <span className={styles.stepRatio}>{previous === null ? "İlk adım" : ratioText(previous)}</span>
    </div>;
  });

  return <figure ref={visibleRef} className={styles.figure} data-reduced={reduced || undefined} aria-labelledby={titleId}>
    <div className={styles.head}>
      <div className={styles.titles}>
        <figcaption id={titleId} className={styles.title}>{label}</figcaption>
        {description && <p className={styles.description}>{description}</p>}
      </div>
      <div className={styles.actions}>
        {showViews && parts.length > 0 && <SegmentedControl label="Görünüm" value={view} onValueChange={setView} options={viewOptions} />}
        {actions}
      </div>
    </div>
    {empty ? <p className={styles.empty}>{emptyText}</p> : <div ref={box} className={styles.body} data-vertical={vertical || undefined}>
      {!vertical && <div className={styles.heads} style={{ gridTemplateColumns: `repeat(${count}, minmax(0, 1fr))` }} aria-hidden="true">{heads}</div>}
      <div className={styles.stage}>
        <div className={styles.focus} role="group" aria-roledescription="huni grafiği" aria-label={`${label}; ok tuşlarıyla adımlar arasında gezin`} tabIndex={0} onKeyDown={onKeyDown} onBlur={() => pick(null)}>
          <svg className={styles.svg} width={vertical ? breadth : length} height={vertical ? length : HEIGHT} aria-hidden="true" data-revealed={revealed || undefined}
            onPointerMove={event => { if (event.pointerType === "mouse" || event.buttons) pick(stepAt(event)); }} onPointerDown={event => pick(stepAt(event))} onPointerLeave={event => { if (event.pointerType === "mouse") pick(null); }}>
            {active !== null && <rect className={styles.column} x={vertical ? 0 : active * stepSize} y={vertical ? active * stepSize : 0} width={vertical ? breadth : stepSize} height={vertical ? stepSize : HEIGHT} />}
            <g className={styles.bands} data-vertical={vertical || undefined}>
              {bands.map(band => <path key={band.key} className={styles.band} d={bandPath(band)} style={{ fill: band.key === "total" ? seriesColor(0) : seriesColor(Math.max(0, parts.findIndex(part => part.key === band.key))) }} />)}
            </g>
            {!reduced && onScreen && revealed && bands.map(band => <g key={band.key} className={styles.dots}>{[0, 1, 2, 3].map(at => <circle key={at} r={2} className={styles.dot}>
              <animateMotion dur="7s" begin={`${-(at * 1.75)}s`} repeatCount="indefinite" path={centerPath(band)} />
            </circle>)}</g>)}
          </svg>
          {!vertical && <div className={styles.drops} aria-hidden="true">{steps.slice(1).map((step, at) => <span key={step.key} className={styles.drop} style={{ left: (at + 1) * stepSize }}>{dropText(kind, steps[at]!.value, step.value)}</span>)}</div>}
        </div>
        {vertical && <div className={styles.rows} style={{ height: length }} aria-hidden="true">{heads}</div>}
        {footprint && ratios && <div className={styles.tip} style={vertical ? { top: (active ?? 0) * stepSize, right: 0 } : { left: tipCenter }} role="presentation">
          <strong>{footprint.label}</strong>
          <span>{countText(kind, footprint.value)}</span>
          <span>İlk adıma göre {ratioText(ratios.first)}</span>
          {ratios.previous !== null && <span>Önceki adımdan {ratioText(ratios.previous)} kaldı</span>}
          {footprint.parts?.map(part => <span key={part.key} className={styles.tipPart}>{part.label}: {countText(kind, part.value)}</span>)}
        </div>}
      </div>
    </div>}
    <div className={styles.srOnly}><table>
      <caption>{label}</caption>
      <thead><tr><th scope="col">Adım</th><th scope="col">Değer</th><th scope="col">Önceki adımdan</th><th scope="col">İlk adıma göre</th></tr></thead>
      <tbody>{steps.map((step, at) => { const r = stepRatios(steps, at); return <tr key={step.key}><th scope="row">{step.label}</th><td>{countText(kind, step.value)}</td><td>{r.previous === null ? "—" : ratioText(r.previous)}</td><td>{ratioText(r.first)}</td></tr>; })}</tbody>
    </table></div>
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{active === null ? "" : stepAnnouncement(kind, steps, active)}</p>
  </figure>;
}

export default FunnelChart;
